package com.mengzhihua.crm.sales.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.Activity;import com.mengzhihua.crm.sales.service.ActivityService;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/activities")public class ActivityController{private final ActivityService s;public ActivityController(ActivityService x){s=x;}@GetMapping public Result<PageResult<Activity>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)com.mengzhihua.crm.common.Enums.RelatedType relatedType,@RequestParam(required=false)Long relatedId,@RequestParam(required=false)com.mengzhihua.crm.common.Enums.ActivityStatus status){return Result.ok(s.list(page,size,keyword,relatedType,relatedId,status));}@GetMapping("/{id}")public Result<Activity> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<Activity> add(@RequestBody Activity x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<Activity> edit(@PathVariable Long id,@RequestBody Activity x){x.setId(id);return Result.ok(s.save(x));}@PutMapping("/{id}/complete")public Result<Activity> complete(@PathVariable Long id){return Result.ok(s.complete(id));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}}
